const extracted = $input.all();
const sourceDocs = $('Prepare Document').all();

// Group documents by email_id
const grouped = {};

for (let i = 0; i < extracted.length; i++) {
  const source = sourceDocs[i]?.json;

  if (!source) continue;

  const emailId = source.email_id;
  const type = source.document_type;
  const data = extracted[i].json.output ?? extracted[i].json;

  if (!grouped[emailId]) {
    grouped[emailId] = {};
  }

  grouped[emailId][type] = data;
}

// Fields that must be compared
const fields = [
  "shipper",
  "consignee",
  "notify_party",
  "port_of_loading",
  "port_of_discharge",
  "container_count",
  "gross_weight_kg"
];

function normalizeText(value) {
  if (value === null || value === undefined) {
    return "";
  }

  return String(value)
    .trim()
    .toUpperCase()
    .replace(/\s+/g, " ")
    .replace(/[.,]/g, "");
}

// Produce ONE result per email
const results = [];

for (const [emailId, docs] of Object.entries(grouped)) {

  const si = docs.SI;
  const bl = docs.BL;

  // Missing SI or BL
  if (!si || !bl) {
    results.push({
      json: {
        email_id: emailId,
        status: "NEEDS_REVIEW",
        review_reason: "missing_attachment",
        has_defect: false,
        defect_fields: []
      }
    });

    continue;
  }

  const defectFields = [];

  for (const field of fields) {

    const siValue = si[field];
    const blValue = bl[field];

    if (
      field === "container_count" ||
      field === "gross_weight_kg"
    ) {
      if (Number(siValue) !== Number(blValue)) {
        defectFields.push(field);
      }
    } else {
      if (normalizeText(siValue) !== normalizeText(blValue)) {
        defectFields.push(field);
      }
    }
  }

  const hasDefect = defectFields.length > 0;

  results.push({
    json: {
      email_id: emailId,
      status: hasDefect ? "MISMATCH" : "OK",
      review_reason: null,
      has_defect: hasDefect,
      defect_fields: defectFields,

      // Keep temporarily for debugging
      si_extracted: si,
      bl_extracted: bl
    }
  });
}

return results;

