// ==========================================
// PORT ALIAS DATABASE
// ==========================================
// Tier 2: known port names / aliases → UN/LOCODE
const PORT_ALIASES = {
  // Malaysia
  "PORT KLANG": "MYPKG",
  "PORT KLANG WESTPORT": "MYPKG",
  "PORT KLANG MALAYSIA": "MYPKG",
  "KLANG": "MYPKG",

  // China
  "NANTONG": "CNNTG",
  "NANTONG CHINA": "CNNTG",

  // Pakistan
  "KARACHI": "PKKHI",
  "KARACHI PAKISTAN": "PKKHI",

  // Peru
  "CALLAO": "PECLL",
  "CALLAO PERU": "PECLL"
};


// ==========================================
// BASIC TEXT NORMALIZATION
// ==========================================
function cleanPort(value) {
  if (value === null || value === undefined) {
    return "";
  }

  return String(value)
    .toUpperCase()
    .trim()
    .replace(/[(),.]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}


// ==========================================
// TIER 1 — EXPLICIT UN/LOCODE
// ==========================================
function extractLocode(value) {
  if (!value) {
    return null;
  }

  const text = String(value).toUpperCase();

  /*
    Only trust a UN/LOCODE when explicitly written
    inside parentheses.

    Examples:
      PORT KLANG (MYPKG) → MYPKG
      NANTONG (CNNTG)     → CNNTG

    This prevents normal five-letter words such as
    KLANG and CHINA from being mistaken for LOCODEs.
  */

  const match = text.match(/\(([A-Z]{2}[A-Z0-9]{3})\)/);

  if (!match) {
    return null;
  }

  return match[1];
}


// ==========================================
// RESOLVE ONE PORT
// ==========================================
function resolvePort(value) {

  // Missing value
  if (
    value === null ||
    value === undefined ||
    String(value).trim() === ""
  ) {
    return {
      original: value,
      normalized: null,
      method: "missing",
      confidence: 0
    };
  }


  // ----------------------------------------
  // TIER 1: Explicit UN/LOCODE
  // ----------------------------------------
  const locode = extractLocode(value);

  if (locode) {
    return {
      original: value,
      normalized: locode,
      method: "locode",
      confidence: 1.0
    };
  }


  // Clean text before alias matching
  const cleaned = cleanPort(value);


  // ----------------------------------------
  // TIER 2: Known aliases
  // ----------------------------------------
  if (PORT_ALIASES[cleaned]) {
    return {
      original: value,
      normalized: PORT_ALIASES[cleaned],
      method: "alias",
      confidence: 0.95
    };
  }


  // ----------------------------------------
  // TIER 3: Conservative normalization
  // ----------------------------------------
  /*
    IMPORTANT:
    We do NOT guess unknown ports yet.

    Example:
      "PORT ABC."
      becomes
      "PORT ABC"

    But we do not automatically decide that it is
    equivalent to another port.

    This reduces false positive matches.
  */

  return {
    original: value,
    normalized: cleaned,
    method: "normalized_text",
    confidence: 0.70
  };
}


// ==========================================
// PROCESS ALL DOCUMENTS
// ==========================================
return items.map(item => {

  // Supports both:
  // { output: {...} }
  // and normal {...} objects
  const data = item.json.output ?? item.json;

  const loading =
    resolvePort(data.port_of_loading);

  const discharge =
    resolvePort(data.port_of_discharge);


  return {
    json: {

      // Keep original data
      ...item.json,

      // Detailed debugging information
      port_resolution: {

        port_of_loading: loading,

        port_of_discharge: discharge
      },

      // Values that M4 comparison will eventually use
      normalized_port_of_loading:
        loading.normalized,

      normalized_port_of_discharge:
        discharge.normalized
    }
  };
});

return [
