const items = $input.all();


// ==========================================
// WEIGHT NORMALIZATION
// ==========================================
function normalizeWeight(value) {

  if (
    value === null ||
    value === undefined ||
    String(value).trim() === ""
  ) {
    return {
      original: value,
      normalized_kg: null,
      method: "missing",
      confidence: 0
    };
  }

  // Already a number:
  // assume M3 already converted it to kilograms
  if (typeof value === "number") {
    return {
      original: value,
      normalized_kg: value,
      method: "already_numeric_kg",
      confidence: 1.0
    };
  }

  let text = String(value)
    .toUpperCase()
    .trim()
    .replace(/,/g, "");

  // Extract first numeric value
  const numberMatch = text.match(/-?\d+(?:\.\d+)?/);

  if (!numberMatch) {
    return {
      original: value,
      normalized_kg: null,
      method: "unresolved",
      confidence: 0
    };
  }

  const amount = Number(numberMatch[0]);

  if (!Number.isFinite(amount) || amount < 0) {
    return {
      original: value,
      normalized_kg: null,
      method: "unresolved",
      confidence: 0
    };
  }


  // ----------------------------------------
  // KG
  // ----------------------------------------
  if (
    /\bKG\b/.test(text) ||
    /\bKGS\b/.test(text) ||
    /\bKILOGRAMS?\b/.test(text)
  ) {
    return {
      original: value,
      normalized_kg: amount,
      method: "kg",
      confidence: 1.0
    };
  }


  // ----------------------------------------
  // METRIC TON / MT
  // ----------------------------------------
  if (
    /\bMT\b/.test(text) ||
    /\bMETRIC\s+TONS?\b/.test(text) ||
    /\bTONNES?\b/.test(text)
  ) {
    return {
      original: value,
      normalized_kg: amount * 1000,
      method: "metric_ton",
      confidence: 1.0
    };
  }


  // ----------------------------------------
  // LB / LBS / POUNDS
  // ----------------------------------------
  if (
    /\bLBS?\b/.test(text) ||
    /\bPOUNDS?\b/.test(text)
  ) {
    const kg = amount * 0.453592;

    return {
      original: value,

      // Round to 3 decimal places
      normalized_kg:
        Math.round(kg * 1000) / 1000,

      method: "lbs",
      confidence: 1.0
    };
  }


  // Unit is unknown.
  // Don't guess.
  return {
    original: value,
    normalized_kg: null,
    method: "unknown_unit",
    confidence: 0.3
  };
}


// ==========================================
// CONTAINER COUNT NORMALIZATION
// ==========================================
function normalizeContainerCount(value) {

  if (
    value === null ||
    value === undefined ||
    String(value).trim() === ""
  ) {
    return {
      original: value,
      normalized_count: null,
      method: "missing",
      confidence: 0
    };
  }


  // Already numeric
  if (typeof value === "number") {

    if (
      Number.isInteger(value) &&
      value >= 0
    ) {
      return {
        original: value,
        normalized_count: value,
        method: "already_numeric",
        confidence: 1.0
      };
    }

    return {
      original: value,
      normalized_count: null,
      method: "invalid_number",
      confidence: 0
    };
  }


  const text = String(value)
    .toUpperCase()
    .trim()
    .replace(/\s+/g, " ");


  // ----------------------------------------
  // Pattern:
  // 2 x 40HC
  // 2 X 40' HC
  // 3 x 20GP
  // ----------------------------------------
  const xPattern =
    text.match(/\b(\d+)\s*[X×]\s*\d+/);

  if (xPattern) {
    return {
      original: value,
      normalized_count: Number(xPattern[1]),
      method: "container_pattern",
      confidence: 1.0
    };
  }


  // ----------------------------------------
  // Pattern:
  // 2 containers
  // 1 container
  // ----------------------------------------
  const containerPattern =
    text.match(/\b(\d+)\s*CONTAINERS?\b/);

  if (containerPattern) {
    return {
      original: value,
      normalized_count:
        Number(containerPattern[1]),
      method: "container_text",
      confidence: 1.0
    };
  }


  // ----------------------------------------
  // String containing only a number
  // "2" → 2
  // ----------------------------------------
  if (/^\d+$/.test(text)) {
    return {
      original: value,
      normalized_count: Number(text),
      method: "numeric_string",
      confidence: 1.0
    };
  }


  // Cannot safely determine container count
  return {
    original: value,
    normalized_count: null,
    method: "unresolved",
    confidence: 0
  };
}


// ==========================================
// PROCESS ALL ITEMS
// ==========================================
return items.map(item => {

  const data =
    item.json.output ?? item.json;

  const weight =
    normalizeWeight(data.gross_weight_kg);

  const containers =
    normalizeContainerCount(
      data.container_count
    );


  return {
    json: {

      // Preserve existing data
      ...item.json,

      // Debugging / audit information
      normalization: {

        gross_weight: weight,

        container_count: containers
      },

      // Values comparator will eventually use
      normalized_gross_weight_kg:
        weight.normalized_kg,

      normalized_container_count:
        containers.normalized_count
    }
  };
});

return [
  {
    json: {
      test_name: "KG format",
      gross_weight_kg: "22,000 KG",
      container_count: "2 x 40HC"
    }
  },

  {
    json: {
      test_name: "Metric tons",
      gross_weight_kg: "22 MT",
      container_count: "2 X 40' HC"
    }
  },

  {
    json: {
      test_name: "Pounds",
      gross_weight_kg: "48501.7 LBS",
      container_count: "2 containers"
    }
  },

  {
    json: {
      test_name: "Already normalized",
      gross_weight_kg: 22000,
      container_count: 2
    }
  },

  {
    json: {
      test_name: "Unknown values",
      gross_weight_kg: "UNKNOWN",
      container_count: "UNKNOWN"
    }
  }
];

