  "PORT KLANG WESTPORT": "MYPKG",
  "PORT KLANG MALAYSIA": "MYPKG",
  "KLANG": "MYPKG",

  "NANTONG": "CNNTG",
  "NANTONG CHINA": "CNNTG",

  "KARACHI": "PKKHI",
