  return cleaned;
}


// ==========================================
// WEIGHT NORMALIZATION
// ==========================================

function normalizeWeight(value) {
  if (
    value === null ||
    value === undefined ||
    String(value).trim() === ""
  ) {
    return null;
  }

  // M3 may already give us kilograms
  if (typeof value === "number") {
    return value;
  }

  const text = String(value)
    .toUpperCase()
    .trim()
    .replace(/,/g, "");

  const numberMatch =
    text.match(/-?\d+(?:\.\d+)?/);

  if (!numberMatch) {
    return null;
  }

  const amount = Number(numberMatch[0]);

  if (!Number.isFinite(amount) || amount < 0) {
    return null;
  }


  // KG
  if (
    /\bKG\b/.test(text) ||
    /\bKGS\b/.test(text) ||
    /\bKILOGRAMS?\b/.test(text)
  ) {
    return amount;
  }


  // Metric tons
  if (
    /\bMT\b/.test(text) ||
    /\bMETRIC\s+TONS?\b/.test(text) ||
    /\bTONNES?\b/.test(text)
  ) {
    return amount * 1000;
  }


  // Pounds
  if (
    /\bLBS?\b/.test(text) ||
    /\bPOUNDS?\b/.test(text)
  ) {
    return amount * 0.453592;
  }


  // Unknown unit
  return null;
}


// ==========================================
// CONTAINER NORMALIZATION
// ==========================================

function normalizeContainerCount(value) {
  if (
    value === null ||
    value === undefined ||
    String(value).trim() === ""
  ) {
    return null;
  }


  if (typeof value === "number") {
    if (
      Number.isInteger(value) &&
      value >= 0
    ) {
      return value;
    }

    return null;
  }


  const text = String(value)
    .toUpperCase()
    .trim()
    .replace(/\s+/g, " ");


  // Example: 2 x 40HC
  const xPattern =
    text.match(/\b(\d+)\s*[X×]\s*\d+/);

  if (xPattern) {
    return Number(xPattern[1]);
  }


  // Example: 2 containers
  const containerPattern =
    text.match(/\b(\d+)\s*CONTAINERS?\b/);

  if (containerPattern) {
    return Number(containerPattern[1]);
  }


  // Example: "2"
  if (/^\d+$/.test(text)) {
    return Number(text);
  }


  return null;
}


// ==========================================
// WEIGHT COMPARISON WITH TOLERANCE
// ==========================================

function weightsEqual(a, b) {
  if (a === null || b === null) {
    return false;
  }

  const difference = Math.abs(a - b);

  /*
    Unit conversions such as LBS → KG can create
    tiny decimal differences.

    Example:
    22000 KG
    vs
    48501.7 LBS → 21999.983 KG

    Difference = 0.017 KG.

    We allow a maximum difference of 0.5 KG.
  */

  return difference <= 0.5;
}


