const PORT_ALIASES = {

  // Malaysia
  "PORT KLANG": "MYPKG",
  "PORT KLANG WESTPORT": "MYPKG",
  "PORT KLANG MALAYSIA": "MYPKG",
  "KLANG": "MYPKG",

