// ==========================================
// NORMALIZE NORMAL TEXT
// ==========================================

function normalizeText(value) {

  if (
    value === null ||
    value === undefined
  ) {
    return "";
  }

  return String(value)
    .trim()
    .toUpperCase()
    .replace(/\s+/g, " ")
    .replace(/[.,]/g, "");
}


// ==========================================
// PORT NORMALIZATION
// ==========================================

function cleanPort(value) {

  if (
    value === null ||
    value === undefined
  ) {
    return "";
  }

  return String(value)
    .toUpperCase()
    .trim()
    .replace(/[(),.]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}


function extractLocode(value) {

  if (!value) {
    return null;
  }

  const text =
    String(value).toUpperCase();

  // Only accept explicit UN/LOCODE in parentheses.
  // Prevents words such as KLANG and CHINA
  // from being detected as LOCODEs.

  const match =
    text.match(/\(([A-Z]{2}[A-Z0-9]{3})\)/);

  if (!match) {
    return null;
  }

  return match[1];
}


function normalizePort(value) {

  if (
    value === null ||
    value === undefined ||
    String(value).trim() === ""
  ) {
    return null;
  }


  // ----------------------------------------
  // TIER 1
  // Explicit UN/LOCODE
  // ----------------------------------------

  const locode =
    extractLocode(value);

  if (locode) {
    return locode;
  }


  // ----------------------------------------
  // TIER 2
  // Alias database
  // ----------------------------------------

  const cleaned =
    cleanPort(value);

  if (PORT_ALIASES[cleaned]) {
    return PORT_ALIASES[cleaned];
  }


  // ----------------------------------------
  // TIER 3
  // Conservative normalized text
  // ----------------------------------------

  return cleaned;
}


// ==========================================
// WEIGHT NORMALIZATION
// ==========================================

function normalizeWeight(value) {

  if (
    value === null ||
    value === undefined ||
    String(value).trim() === ""
  ) {
    return null;
  }


  // Already numeric.
  // Assume M3 already returned KG.
  if (typeof value === "number") {
    return value;
  }


  const text =
    String(value)
      .toUpperCase()
      .trim()
      .replace(/,/g, "");


  const numberMatch =
    text.match(/-?\d+(?:\.\d+)?/);


  if (!numberMatch) {
    return null;
  }


  const amount =
    Number(numberMatch[0]);


  if (
    !Number.isFinite(amount) ||
    amount < 0
  ) {
    return null;
  }


  // ----------------------------------------
  // KG
  // ----------------------------------------

  if (
    /\bKG\b/.test(text) ||
    /\bKGS\b/.test(text) ||
    /\bKILOGRAMS?\b/.test(text)
  ) {
    return amount;
  }


  // ----------------------------------------
  // METRIC TON
  // ----------------------------------------

  if (
    /\bMT\b/.test(text) ||
    /\bMETRIC\s+TONS?\b/.test(text) ||
    /\bTONNES?\b/.test(text)
  ) {
    return amount * 1000;
  }


  // ----------------------------------------
  // POUNDS
  // ----------------------------------------

  if (
    /\bLBS?\b/.test(text) ||
    /\bPOUNDS?\b/.test(text)
  ) {
    return amount * 0.453592;
  }


  // Unknown unit → don't guess
  return null;
}


// ==========================================
// CONTAINER COUNT NORMALIZATION
// ==========================================

function normalizeContainerCount(value) {

  if (
    value === null ||
    value === undefined ||
    String(value).trim() === ""
  ) {
    return null;
  }


  // Already numeric
  if (typeof value === "number") {

    if (
      Number.isInteger(value) &&
      value >= 0
    ) {
      return value;
    }

    return null;
  }


  const text =
    String(value)
      .toUpperCase()
      .trim()
      .replace(/\s+/g, " ");


  // ----------------------------------------
  // Example:
  // 2 x 40HC
  // 2 X 40' HC
  // ----------------------------------------

  const xPattern =
    text.match(/\b(\d+)\s*[X×]\s*\d+/);

  if (xPattern) {
    return Number(xPattern[1]);
  }


  // ----------------------------------------
  // Example:
  // 2 containers
  // 1 container
  // ----------------------------------------

  const containerPattern =
    text.match(/\b(\d+)\s*CONTAINERS?\b/);

  if (containerPattern) {
    return Number(containerPattern[1]);
  }


  // ----------------------------------------
  // Example:
  // "2"
  // ----------------------------------------

  if (/^\d+$/.test(text)) {
    return Number(text);
  }


  // Cannot safely resolve
  return null;
}


// ==========================================
// WEIGHT COMPARISON
// ==========================================

function weightsEqual(a, b) {

  if (
    a === null ||
    b === null
  ) {
    return false;
  }

  const difference =
    Math.abs(a - b);

  // Allow tiny conversion differences.
  // Example:
  //
  // 48501.7 LBS
  // = 21999.983 KG
  //
  // vs
  //
  // 22000 KG

  return difference <= 0.5;
}


